echo "eol=CRLF -> ret=$n2 content=", str_replace(["\r","\n"],["\\r","\\n"],$c2), "\n";
$h3=fopen("php://memory","r+");
$n3=fputcsv($h3,["a","b"]," ","\"","\\");     rewind($h3);
echo "sep=space content=", str_replace("\n","\\n",stream_get_contents($h3)), "\n";
